import {DarkMatterExperience, REALITIES} from './experience.js';
import {MouseTour} from './tour.js';
const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
let exploring=false,opened=false,world=0,activePanel='experience',paused=matchMedia('(prefers-reduced-motion:reduce)').matches;
const worlds=REALITIES;
let journey,tour;
function updateJourney(state){
 exploring=state.mode!=='landing';opened=state.mode==='world';world=state.world||0;
 document.body.classList.toggle('exploring',exploring);document.body.classList.toggle('walking',exploring);
 document.body.dataset.location=state.mode;$('#explorer').hidden=!exploring;
 const r=worlds[world];
 $('#world-label').textContent=state.mode==='lab'?'VELOCITY LABORATORIES':state.mode==='world'?r.episode+(world===4?' / JASON’IN DÜNYASI':' / ALTERNATİF GERÇEKLİK'):'KUTUNUN İÇİNDE / SÜPERPOZİSYON';
 $('#world-title').textContent=state.mode==='lab'?'Kutuya yaklaş.':state.mode==='world'?r.name:'Sonsuz koridor.';
 $('#world-description').textContent=state.mode==='lab'?'Tekerleği kaydır. Kutu’ya yaklaş ve eşiği geç.':state.mode==='world'?r.description:'Kaydırarak ilerle. Kapılar bir başka gerçekliğe açılır.';
 $('#door-count').textContent=state.mode==='lab'?'LABORATUVAR':state.mode==='world'?r.name.toLocaleUpperCase('tr'):'SONSUZ KORİDOR';
 $('#close-door').hidden=state.mode!=='world';$('#door-menu').hidden=false;
 $('#flashlight').setAttribute('aria-pressed',String(state.flashlight));$('#flashlight').setAttribute('aria-label',state.flashlight?'El fenerini kapat':'El fenerini aç');
 $$('[data-world]').forEach(b=>b.classList.toggle('selected',state.mode==='world'&&Number(b.dataset.world)===world));
 if(state.mode==='fallback'){$('#world-title').textContent='Üç boyutlu görünüm açılamadı.';$('#world-description').textContent='WebGL destekli bir tarayıcıyla deneyimi açabilir, hikâye ve karakter arşivini bu tarayıcıda gezebilirsin.';$('#open-door').hidden=true;$('#enter').disabled=true;$('#exit').hidden=true;$('#flashlight').hidden=true;$$('[data-move]').forEach(b=>b.disabled=true);}
}
function updateDoor(){
 const action=$('#open-door');action.hidden=!exploring;
 action.querySelector('span:last-child').textContent=journey?.mode==='lab'?'Kutu’ya gir':journey?.mode==='corridor'?'Bu dünyaya geç':world===4?'Yolculuğu yeniden başlat':'Sonraki evrene geç';
}
journey=new DarkMatterExperience({mount:$('#scene'),onState:updateJourney,onDoor:updateDoor});
tour=new MouseTour(journey,state=>{
 const percent=Math.round(state.progress*100);$('#journey-progress').style.width=percent+'%';$('.journey-progress').setAttribute('aria-valuenow',String(percent));
 const chapter=state.chapter<0?'KUTUYA DOĞRU':worlds[tour.chapters[state.chapter]?.world||0].name.toLocaleUpperCase('tr');if($('#journey-chapter').textContent!==chapter)$('#journey-chapter').textContent=chapter;
 if(journey.mode==='world'&&journey.selected===4){if(state.stop&&$('#world-title').textContent!==state.stop)$('#world-title').textContent=state.stop;const phase=tour.current-tour.chapters.at(-1).start;const label=phase<1.7?'Evin içine gir':phase<3.65?'Mutfağı keşfet':'Baştan keşfet';const span=$('#open-door span:last-child');if(span.textContent!==label)span.textContent=label;}if(state.loading)$('#announcement').textContent='Dünya hazırlanıyor.';
});
$('#enter').onclick=()=>tour.start();$('#scroll-start').onclick=()=>tour.start();$('#exit').onclick=()=>tour.home();
$('#home-nav').onclick=()=>{showPanel('experience');tour.jump(4);$('.site-header').classList.remove('menu-open');};
$('#motion').onclick=()=>{paused=!paused;journey.setPaused(paused);$('#motion').setAttribute('aria-pressed',String(paused));$('#motion').setAttribute('aria-label',paused?'Atmosfer hareketini başlat':'Atmosfer hareketini durdur');$('#motion').textContent=paused?'▷':'Ⅱ'};
$('#open-door').onclick=()=>tour.advance();$('#close-door').onclick=()=>{const c=tour.chapters[tour.chapterAt()];tour.target=c.start+.35;tour.returnLook=true;};
$('#flashlight').onclick=()=>journey.toggleFlashlight();
$('#door-menu').onclick=()=>{const open=$('#world-picker').hidden;$('#world-picker').hidden=!open;$('#door-menu').setAttribute('aria-expanded',String(open));};
async function selectWorld(i){$('#world-picker').hidden=true;$('#door-menu').setAttribute('aria-expanded','false');await tour.jump(i);}
$$('[data-world]').forEach(b=>b.onclick=()=>selectWorld(Number(b.dataset.world)));
$('#back-lab').onclick=()=>{tour.jumpLab();$('#world-picker').hidden=true;};
