let episodes2=[], season=1, episode=0, spoilers=false;
fetch('season2.json').then(r=>r.ok?r.json():[]).then(data=>{episodes2=data;if(activePanel==='episodes'&&season===2)renderEpisodes()}).catch(()=>{});
function panelShell(n,title,description,content){return `<div class="panel-heading"><div><span class="section-label">${n} / DARK MATTER ARŞİVİ</span><h2>${title}</h2></div><p>${description}</p></div>${content}<div class="panel-return"><button data-panel="experience">‹ Deneyime dön</button><span>HER SEÇİM BAŞKA BİR HAYAT.</span></div>`}
function storyHTML(){return panelShell('02','Seçmediğin hayat.<br>Unutamadığın ev.','Blake Crouch’un çok satan romanından bir bilimkurgu gerilimi.',`<div class="story-layout"><div class="story-image"><img src="assets/family.jpg" alt="Jason ve Daniela Dessen evlerinde birbirine sarılıyor" loading="lazy"><div class="image-label"><span>JASON & DANIELA</span><span>© APPLE TV</span></div></div><div class="story-body"><p class="lead">Chicago’da yaşayan fizikçi Jason Dessen, bir gece kendi hayatının başka bir versiyonuna kaçırılır.</p><p>Ailesine dönebilmek için, yaşayabileceği hayatlarla dolu bir gerçeklik labirentinde yolunu bulmak zorundadır. Her kapı bir ihtimaldir. Ama aradığı şey sonsuz seçenek değil, kendi evidir.</p><div class="facts"><div><span>YARATICI</span><strong>Blake Crouch</strong></div><div><span>KAYNAK ROMAN</span><strong>Dark Matter · 2016</strong></div><div><span>YAPIM</span><strong>Sony Pictures TV</strong></div></div><button class="text-button" data-trailer="1"><span class="play-icon">▷</span> Hikâyenin başlangıcını izle</button></div></div><div class="concepts"><article class="concept"><span class="concept-number">01</span><h3>Kutu</h3><p>Dış dünyanın gözleminden yalıtılmış, siyah metal bir eşik. Dizinin kurmaca evreninde, bildiğimiz gerçekliğin sınırlarını aşmaya imkân veren icat.</p></article><article class="concept"><span class="concept-number">02</span><h3>Koridor</h3><p>Aynı yapının sonsuz tekrarı. Bir kapıyı açmak, başka bir dünyayla karşılaşmak. Nereye gittiğin kadar, kendinle ne taşıdığın da önemlidir.</p></article><article class="concept"><span class="concept-number">03</span><h3>Aidiyet</h3><p>Olasılıklar sınırsız olduğunda, insan neyi seçer? Dark Matter’ın kalbinde seçimler, pişmanlıklar ve eve dönme arzusu var.</p></article></div><div class="season-banner"><div><span class="section-label">2. SEZON YAYINDA</span><h3>Kapıların ardındaki hikâye devam ediyor.</h3><p>28 Ağustos – 30 Ekim 2026 · 10 bölüm · Her cuma Apple TV’de</p></div><button class="text-button" data-trailer="2"><span class="play-icon">▷</span> 2. sezon fragmanı</button></div>`)}
function castHTML(){return panelShell('03','Aynı yüz.<br>Başka bir hayat.','Sonsuz olasılıkların içinde, hikâyeyi taşıyan insanlar.',`<div class="cast-grid">${cast.map((c,i)=>`<button class="cast-card" data-cast="${i}" aria-label="${c.name}, ${c.actor}, karakteri keşfet"><div class="cast-image"><img src="assets/${c.image}" alt="${c.actor}, ${c.name} rolünde" style="object-position:${c.pos}" loading="lazy"><span class="cast-num">0${i+1} / ${c.role.split(' · ')[0]}</span></div><h3>${c.name}</h3><p>${c.actor}</p><span class="cast-open">+</span></button>`).join('')}</div>`)}
function episodesHTML(){return panelShell('04','Her bölüm,<br>yeni bir kapı.','Bölüm adları özgün hâliyle. Özetleri görmek için spoiler seçeneğini aç.',`<div class="archive-controls"><div class="season-tabs" role="tablist" aria-label="Sezon seçimi"><button class="season-tab ${season===1?'active':''}" data-season="1" role="tab" aria-selected="${season===1}">Sezon 01</button><button class="season-tab ${season===2?'active':''}" data-season="2" role="tab" aria-selected="${season===2}">Sezon 02</button></div><label class="spoiler-label"><input type="checkbox" id="spoilers" ${spoilers?'checked':''}> Bölüm özetlerini göster</label></div><div class="episode-layout"><div class="episode-list" id="episode-list"></div><div class="episode-feature" id="episode-feature"></div></div><div class="upcoming-note" id="season-info"></div>`)}
function renderEpisodes(){const eps=season===1?episodes1:episodes2;$('#episode-list').innerHTML=eps.map((e,i)=>`<button class="episode-button ${i===episode?'active':''}" data-episode="${i}" aria-label="Bölüm ${i+1}: ${e[0]}" aria-pressed="${i===episode}"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${e[0]}</h3><small>${e[1]}</small></div><span>+</span></button>`).join('');if(!eps.length){$('#episode-feature').innerHTML='<p>İkinci sezon Apple TV’de yayında. Güncel bölüm arşivini Apple TV’den keşfet.</p><a class="text-button" href="https://www.apple.com/tv-pr/originals/dark-matter/episodes-images/" target="_blank" rel="noopener">Resmî bölüm arşivi</a>';}else{const e=eps[episode]||eps[0];$('#episode-feature').innerHTML=`<img src="assets/${e[3]}" alt="Dark Matter dizisinden resmî tanıtım karesi"><span class="section-label">SEZON 0${season} · BÖLÜM ${String(episode+1).padStart(2,'0')}${e[4]==='upcoming'?' · YAKINDA':''}</span><h3>${e[0]}</h3><p>${spoilers?e[2]:'Her kapının ardında keşfedilmeyi bekleyen bir hikâye var. Bölüm özetleri şu an kapalı.'}</p><a class="text-button" href="https://tv.apple.com/us/show/dark-matter/umc.cmc.4luj45vtqpmjsvb6sc2675oeg" target="_blank" rel="noopener">${e[4]==='upcoming'?'Apple TV’de önizle':'Apple TV’de izle'}</a>`;}$('#season-info').textContent=season===1?'1. sezon · 9 bölüm · 8 Mayıs – 26 Haziran 2024':'2. sezon · 10 bölüm · 28 Ağustos – 30 Ekim 2026. Yayımlanan 6 bölüm ve resmen duyurulan 7. bölüm gösteriliyor. Bilgiler 5 Ekim 2026 tarihinde kontrol edildi.';$$('[data-episode]').forEach(b=>b.onclick=()=>{episode=Number(b.dataset.episode);renderEpisodes()});}
function showPanel(name){activePanel=name;journey.setActive(name==='experience');$$('.nav-link').forEach(b=>{b.classList.toggle('active',b.dataset.panel===name);b.setAttribute('aria-current',b.dataset.panel===name?'page':'false')});$('.site-header').classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');document.body.classList.toggle('content-open',name!=='experience');$('#experience').hidden=name!=='experience';$('#content-panel').hidden=name==='experience';if(name==='experience'){history.replaceState(null,'',location.pathname);journey.render();return;}$('#content-panel').innerHTML=name==='story'?storyHTML():name==='characters'?castHTML():episodesHTML();$('#content-panel').scrollTop=0;bindPanel();$('#content-panel').focus({preventScroll:true});if(name==='episodes')renderEpisodes();history.replaceState(null,'',`#${name}`);}
function bindPanel(){$$('[data-panel]').forEach(b=>b.onclick=()=>showPanel(b.dataset.panel));$$('[data-trailer]').forEach(b=>b.onclick=()=>openTrailer(Number(b.dataset.trailer)));$$('[data-cast]').forEach(b=>b.onclick=()=>openCharacter(Number(b.dataset.cast)));$$('[data-season]').forEach(b=>b.onclick=()=>{season=Number(b.dataset.season);episode=0;showPanel('episodes')});if($('#spoilers'))$('#spoilers').onchange=e=>{spoilers=e.target.checked;renderEpisodes()};}
bindPanel();$('.wordmark').onclick=e=>{e.preventDefault();showPanel('experience');if(exploring)$('#exit').click();history.replaceState(null,'',location.pathname)};$('#menu-toggle').onclick=()=>{const open=$('.site-header').classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));};
const modal=$('#modal');let previousFocus=null;
function showModal(html){journey.setActive(false);previousFocus=document.activeElement;$('#modal-content').innerHTML=html;modal.showModal();$('.modal-close').focus();}
$('.modal-close').onclick=()=>modal.close();modal.addEventListener('close',()=>{journey.setActive(activePanel==='experience');$('#modal-content').innerHTML='';previousFocus?.focus()});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function openTrailer(s=1){const id=s===1?'j6ucGt_Xp14':'zhB6_1UbR7s';showModal(`<span class="modal-eyebrow">RESMÎ APPLE TV FRAGMANI</span><h2 class="modal-heading">Dark Matter · Sezon 0${s}</h2><iframe class="trailer-frame" src="https://www.youtube-nocookie.com/embed/${id}?autoplay=1" title="Dark Matter ${s}. sezon resmî fragmanı" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><div class="trailer-options"><button data-trailer-season="1" class="${s===1?'active':''}">1. sezon</button><button data-trailer-season="2" class="${s===2?'active':''}">2. sezon</button><a href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener">YouTube’da aç</a></div>`);$$('[data-trailer-season]').forEach(b=>b.onclick=()=>{modal.close();openTrailer(Number(b.dataset.trailerSeason))})}$('#trailer').onclick=()=>openTrailer(1);
function openCharacter(i){const c=cast[i];showModal(`<div class="character-modal"><img src="assets/${c.image}" alt="${c.actor}" style="object-position:${c.pos}"><div><span class="modal-eyebrow">${c.role}</span><h2>${c.name}</h2><span class="actor">${c.actor}</span><p>${c.description}</p><p style="color:#d2c3b7">${c.question}</p></div></div>`)}
$('#credits').onclick=()=>showModal(`<span class="modal-eyebrow">PROJE & KAYNAKLAR</span><h2 class="modal-heading">Bir gerçekliğe daha hoş geldin.</h2><p class="modal-text">Bu site Dark Matter için hazırlanmış bağımsız, ticari olmayan bir hayran deneyimidir. Apple, Sony Pictures Television veya Blake Crouch ile bağlantılı değildir.</p><p class="modal-text">Laboratuvar ve Kutu, yapım tasarımcısı Patricio Farrell’ın set çizimleri ve Apple’ın resmî kareleri referans alınarak yeniden modellenmiştir. Dış dünyalar MPC ve FOLKS’un yayımladığı sahnelerden araştırılmıştır. Jason’ın özgün evinin ahşap işleri, salonu ve lacivert mutfağı tasarımcının yayımladığı Jason1 set fotoğraflarına dayanır; oda bağlantıları keşif için yeniden düzenlenmiştir. Üç boyutlu modeller bu site için oluşturulmuştur; dizinin özgün 3D varlıkları değildir. Bilgiler 5 Ekim 2026 tarihinde kontrol edilmiştir.</p><div class="modal-links"><a href="https://www.apple.com/tv-pr/originals/dark-matter/" target="_blank" rel="noopener">Apple TV · Resmî Dark Matter basın sayfası</a><a href="https://www.apple.com/tv-pr/originals/dark-matter/episodes-images/" target="_blank" rel="noopener">Apple TV · Bölümler ve görseller</a><a href="https://images.apple.com/tv-pr/news/2026/07/apple-tvs-sci-fi-thriller-dark-matter-takes-over-san-diego-comic-cons-hall-h-to-unveil-season-two-trailer/" target="_blank" rel="noopener">Apple TV · İkinci sezon duyurusu</a><a href="https://digital.copcomm.com/i/1529668-november-december-2024/65" target="_blank" rel="noopener">Art Directors Guild · Patricio Farrell’ın set tasarımları</a><a href="https://www.icg600.com/news-articles/news/divergent" target="_blank" rel="noopener">ICG · Dizinin ışık ve görüntü tasarımı</a><a href="https://www.mpcvfx.com/en/filmography/dark-matter/" target="_blank" rel="noopener">MPC · Alternatif Chicago dünyaları</a><a href="https://folksvfx.com/" target="_blank" rel="noopener">FOLKS · Donmuş Chicago görsel efektleri</a><a href="https://blakecrouch.com/books/dark-matter/" target="_blank" rel="noopener">Blake Crouch · Kaynak roman</a><a href="https://www.explorethesilo.com/" target="_blank" rel="noopener">Explore the Silo · Deneyim referansı</a></div><p class="modal-text">Dark Matter © ilgili hak sahipleri. Dizi kareleri © Apple TV. Apple tanıtım kareleri kişisel ve editoryal, ticari olmayan kullanım koşulları kapsamında kullanılmıştır. Referans karelerinin kaynakları Apple, MPC ve FOLKS’tur; tüm dizi görsellerinin hakları ilgili sahiplerinde kalır.</p>`);
let audioContext,master,soundOn=false;
$('#sound').onclick=async()=>{try{if(!audioContext){audioContext=new AudioContext();master=audioContext.createGain();master.gain.value=0;master.connect(audioContext.destination);[45,67.5,90].forEach((freq,i)=>{const osc=audioContext.createOscillator();osc.type='sine';osc.frequency.value=freq;const g=audioContext.createGain();g.gain.value=.09/(i+1);osc.connect(g);g.connect(master);osc.start()});const length=audioContext.sampleRate*3;const buffer=audioContext.createBuffer(1,length,audioContext.sampleRate);const d=buffer.getChannelData(0);let last=0;for(let i=0;i<length;i++){last=(last+Math.random()*.02-.01)/1.02;d[i]=last;}const noise=audioContext.createBufferSource();noise.buffer=buffer;noise.loop=true;const filter=audioContext.createBiquadFilter();filter.type='lowpass';filter.frequency.value=260;noise.connect(filter);filter.connect(master);noise.start();}await audioContext.resume();soundOn=!soundOn;master.gain.setTargetAtTime(soundOn ? 0.55 : 0,audioContext.currentTime,.4);$('#sound').setAttribute('aria-pressed',String(soundOn));$('#sound').setAttribute('aria-label',soundOn?'Atmosfer sesini kapat':'Atmosfer sesini aç');$('#sound-label').textContent=soundOn?'SES AÇIK':'SES KAPALI';}catch{$('#announcement').textContent='Ses bu tarayıcıda kullanılamıyor.'}};
document.addEventListener('visibilitychange',()=>{if(master)master.gain.setTargetAtTime(!document.hidden&&soundOn ? 0.55 : 0,audioContext.currentTime,.3)});
if(['story','characters','episodes'].includes(location.hash.slice(1)))showPanel(location.hash.slice(1));

$('#control-help').onclick=()=>showModal(`<span class="modal-eyebrow">FARE İLE EVRENİ KEŞFET</span><h2 class="modal-heading">Kaydır. Bak. Geç.</h2><div class="control-grid"><p><strong>Tekerleği aşağı kaydır:</strong> Kutu’ya gir, koridorda ilerle, kapıdan dünyaya geç.</p><p><strong>Yukarı kaydır:</strong> Aynı yol boyunca geri dön.</p><p><strong>Dikey sürükle:</strong> Tekerlek kullanmadan evrenler arasında ileri / geri git.</p><p><strong>Yana sürükle:</strong> Etrafına hızlıca bak. Bıraktığında bakışın o noktada kalır.</p><p><strong>Kapılar:</strong> Bir evrene doğrudan git. Jason’ın evini menüden de açabilirsin.</p></div><p class="modal-text">Telefonda dikey kaydırarak ilerle, yana sürükleyerek bak. Klavye gerekmez. Yolculuk Jason’ın kendi dünyasında, Dessen ailesinin evinde tamamlanır.</p>`);
$('#reference').onclick=()=>{const r=journey.reference();const mode=journey.mode;const image=r?r.image:mode==='corridor'?'corridor-reference.jpg':'lab-reference.jpg';const title=r?r.name:mode==='corridor'?'Sonsuz koridor':'Velocity laboratuvarı';const source=r?(world===4?'Apple TV':world===1?'FOLKS VFX':'MPC VFX'):'Apple TV';showModal(`<span class="modal-eyebrow">DİZİDEN SAHNE REFERANSI · ${source}</span><h2 class="modal-heading">${title}</h2><img class="reference-image" id="reference-photo" src="assets/${image}" alt="Dark Matter ${title} sahnesinin yapım ekibi tarafından yayımlanan karesi">${world===4&&mode==='world'?'<div class="trailer-options"><button data-home-reference="home-reference.jpg">Mutfak · S1E1</button><button data-home-reference="home-stairs-reference.jpg">Ahşap merdiven · S1E8</button></div>':''}<p class="modal-text">Mekânın mimari, ışık ve atmosferini bu referanslarla yeniden modelledik. Kare dizinin özgün görüntüsüdür.${world===4&&mode==='world'?' Evin oda bağlantıları bu keşif için yeniden düzenlenmiştir.':''}</p>`);$$('[data-home-reference]').forEach(b=>b.onclick=()=>{$('#reference-photo').src='assets/'+b.dataset.homeReference;$('#reference-photo').alt=b.textContent+' · Apple TV resmî karesi';});};
// Page tools share the same scroll route and destinations as mouse navigation.
const modelContext=document.modelContext||navigator.modelContext;
if(modelContext?.registerTool){
 const lifecycle=new AbortController();addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const result=data=>({content:[{type:'text',text:JSON.stringify(data)}]});
 const register=tool=>{const execute=tool.execute;tool.execute=async input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!(k in tool.inputSchema.properties))||(tool.inputSchema.required||[]).some(k=>!(k in input)))return result({error:'Geçersiz araç girdisi.'});if(journey.failed&&tool.name!=='get_dark_matter_state'&&tool.name!=='navigate_dark_matter_archive')return result({error:'Üç boyutlu görünüm kullanılamıyor.'});return execute(input);};tool.annotations={readOnlyHint:tool.name==='get_dark_matter_state',untrustedContentHint:false};try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 const state=()=>({location:journey.mode,world:journey.mode==='world'?worlds[journey.selected].name:null,progress:Math.round(tour.current/tour.total*100),position:{x:Number(journey.position.x.toFixed(2)),z:Number(journey.position.z.toFixed(2))}});
 register({name:'get_dark_matter_state',description:'Read the visible scroll journey location, world and progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async()=>result(state())});
 register({name:'scroll_dark_matter_journey',description:'Advance or reverse the mouse-driven camera route. Positive pixels go forward; negative go back. Same action as mouse wheel.',inputSchema:{type:'object',properties:{pixels:{type:'number',minimum:-2000,maximum:2000}},required:['pixels'],additionalProperties:false},execute:async({pixels})=>{if(!Number.isFinite(pixels)||Math.abs(pixels)>2000)return result({error:'Kaydırma -2000 ile 2000 arasında olmalı.'});showPanel('experience');tour.scroll(pixels);await new Promise(resolve=>setTimeout(resolve,650));return result(state());}});
 register({name:'go_to_dark_matter_world',description:'Animate to a world: 1 Ash, 2 Frozen, 3 Utopian, 4 Flooded, 5 Jason’s original Chicago and Dessen house.',inputSchema:{type:'object',properties:{world:{type:'integer',minimum:1,maximum:5}},required:['world'],additionalProperties:false},execute:async({world})=>{if(!Number.isInteger(world)||world<1||world>5)return result({error:'Dünya 1–5 arasında olmalı.'});showPanel('experience');await selectWorld(world-1);return result(state());}});
 register({name:'advance_dark_matter_journey',description:'Use the visible continue/next-world action. Enters Box, passes a world door or proceeds to the next universe.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async()=>{showPanel('experience');tour.advance();await new Promise(resolve=>setTimeout(resolve,950));return result(state());}});
 register({name:'navigate_dark_matter_archive',description:'Open a visible archive panel or return to the experience.',inputSchema:{type:'object',properties:{panel:{type:'string',enum:['experience','story','characters','episodes']}},required:['panel'],additionalProperties:false},execute:async({panel})=>{if(!['experience','story','characters','episodes'].includes(panel))return result({error:'Geçersiz panel.'});showPanel(panel);return result({panel});}});
}
